// ============================================
// FETCH ALL MARKET DATA - MarketPulse v6.0
// IPv4 Fix: Uses custom DNS resolver
// New: Market Indices + Gold Screener
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const FRED_API_KEY = 'YOUR_FRED_API_KEY_HERE';

const results = {
  fearGreedValue: 'N/A',
  fearGreedClassification: 'Unknown',
  fearGreedChange1d: 'N/A',
  fearGreedChange1w: 'N/A',
  gdpValue: 'N/A',
  gdpYear: 'N/A',
  cpiValue: 'N/A',
  cpiYear: 'N/A',
  unemploymentValue: 'N/A',
  unemploymentYear: 'N/A',
  fedRateValue: 'N/A',
  treasury10Y: 'N/A',
  sp500: 'N/A',
  sp500Change: 'N/A',
  dowJones: 'N/A',
  dowJonesChange: 'N/A',
  vix: 'N/A',
  vixChange: 'N/A',
  gold: 'N/A',
  goldChange: 'N/A',
  headlines: 'No headlines available'
};

function formatDate(dateStr) {
  if (!dateStr) return 'N/A';
  const d = new Date(dateStr);
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return months[d.getMonth()] + ' ' + d.getFullYear();
}

async function fetchWithRetry(url, options = {}, retries = 3) {
  for (let i = 0; i < retries; i++) {
    try {
      const response = await $http.request({
        method: 'GET',
        url: url,
        headers: options.headers || {},
        timeout: options.timeout || 30000,
        ...(options.json === false ? { encoding: 'utf-8', json: false } : {})
      });
      return response;
    } catch (e) {
      if (i === retries - 1) throw e;
      await new Promise(r => setTimeout(r, 1000 * (i + 1)));
    }
  }
}

// 1. FETCH CNN FEAR & GREED INDEX
try {
  const fgData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://production.dataviz.cnn.io/index/fearandgreed/graphdata',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
      'Referer': 'https://www.cnn.com/markets/fear-and-greed',
      'Accept': 'application/json'
    },
    timeout: 30000
  });

  if (fgData && fgData.fear_and_greed) {
    const fg = fgData.fear_and_greed;
    results.fearGreedValue = Math.round(fg.score);
    results.fearGreedClassification = fg.rating ? 
      fg.rating.charAt(0).toUpperCase() + fg.rating.slice(1) : 'Unknown';

    if (fg.previous_close !== null && fg.previous_close !== undefined) {
      const d = Math.round(fg.score - fg.previous_close);
      results.fearGreedChange1d = (d >= 0 ? '+' : '') + d;
    }
    if (fg.previous_1_week !== null && fg.previous_1_week !== undefined) {
      const w = Math.round(fg.score - fg.previous_1_week);
      results.fearGreedChange1w = (w >= 0 ? '+' : '') + w;
    }
  }
} catch (e) { 
  console.log('Fear & Greed error: ' + e.message); 
}

// 2. FETCH MARKET INDICES & GOLD (Yahoo Finance)
const indices = [
  { symbol: '^GSPC', namePrice: 'sp500', nameChange: 'sp500Change', label: 'S&P 500' },
  { symbol: '^DJI', namePrice: 'dowJones', nameChange: 'dowJonesChange', label: 'Dow Jones' },
  { symbol: '^VIX', namePrice: 'vix', nameChange: 'vixChange', label: 'VIX' },
  { symbol: 'GC=F', namePrice: 'gold', nameChange: 'goldChange', label: 'Gold' }
];

for (const idx of indices) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(idx.symbol) + '?interval=1d&range=1d',
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 15000
    });

    if (data && data.chart && data.chart.result && data.chart.result[0]) {
      const meta = data.chart.result[0].meta;
      const price = meta.regularMarketPrice;
      const prevClose = meta.chartPreviousClose || meta.previousClose;

      if (price) {
        // Format price based on type
        if (idx.symbol === '^VIX') {
          results[idx.namePrice] = price.toFixed(2);
        } else if (idx.symbol === 'GC=F') {
          results[idx.namePrice] = '$' + price.toFixed(2);
        } else {
          results[idx.namePrice] = price.toFixed(2);
        }

        if (prevClose && prevClose > 0) {
          const changePct = ((price - prevClose) / prevClose) * 100;
          const sign = changePct >= 0 ? '+' : '';
          results[idx.nameChange] = sign + changePct.toFixed(2) + '%';
        }
      }
    }
    // Rate limit: small delay between requests
    await new Promise(r => setTimeout(r, 500));
  } catch (e) {
    console.log(idx.label + ' error: ' + e.message);
  }
}

// 3. FETCH FRED DATA - UNEMPLOYMENT RATE
try {
  const unempData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=UNRATE&api_key=' + FRED_API_KEY + '&file_type=json&limit=1&sort_order=desc',
    timeout: 30000
  });

  if (unempData && unempData.observations && unempData.observations[0]) {
    const obs = unempData.observations[0];
    results.unemploymentValue = obs.value + '%';
    results.unemploymentYear = formatDate(obs.date);
  }
} catch (e) { 
  console.log('FRED Unemployment error: ' + e.message);
}

// 4. FETCH FRED DATA - CPI INFLATION (YoY calculation)
try {
  const cpiData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=CPIAUCSL&api_key=' + FRED_API_KEY + '&file_type=json&limit=13&sort_order=desc',
    timeout: 30000
  });

  if (cpiData && cpiData.observations && cpiData.observations.length >= 13) {
    const latest = parseFloat(cpiData.observations[0].value);
    const yearAgo = parseFloat(cpiData.observations[12].value);
    const yoyChange = ((latest - yearAgo) / yearAgo) * 100;
    results.cpiValue = yoyChange.toFixed(2) + '%';
    results.cpiYear = formatDate(cpiData.observations[0].date);
  }
} catch (e) { 
  console.log('FRED CPI error: ' + e.message);
}

// 5. FETCH FRED DATA - GDP GROWTH RATE (Quarterly)
try {
  const gdpData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=A191RL1Q225SBEA&api_key=' + FRED_API_KEY + '&file_type=json&limit=1&sort_order=desc',
    timeout: 30000
  });

  if (gdpData && gdpData.observations && gdpData.observations[0]) {
    const obs = gdpData.observations[0];
    const sign = parseFloat(obs.value) >= 0 ? '+' : '';
    results.gdpValue = sign + obs.value + '% (QoQ)';
    results.gdpYear = formatDate(obs.date);
  }
} catch (e) { 
  console.log('FRED GDP error: ' + e.message);
}

// 6. FETCH FED FUNDS RATE
try {
  const fedData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=DFEDTARU&api_key=' + FRED_API_KEY + '&file_type=json&limit=10&sort_order=desc',
    timeout: 30000
  });

  if (fedData && fedData.observations) {
    for (let i = 0; i < fedData.observations.length; i++) {
      const val = fedData.observations[i].value;
      if (val && val !== '.' && val !== 'null' && parseFloat(val) > 0) {
        results.fedRateValue = parseFloat(val).toFixed(2) + '%';
        break;
      }
    }
  }
} catch (e) { 
  console.log('FRED Fed Rate error: ' + e.message); 
}

// 7. FETCH 10-YEAR TREASURY YIELD
try {
  const treasuryData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=DGS10&api_key=' + FRED_API_KEY + '&file_type=json&limit=10&sort_order=desc',
    timeout: 30000
  });

  if (treasuryData && treasuryData.observations) {
    for (let i = 0; i < treasuryData.observations.length; i++) {
      const val = treasuryData.observations[i].value;
      if (val && val !== '.' && val !== 'null' && parseFloat(val) > 0) {
        results.treasury10Y = parseFloat(val).toFixed(2) + '%';
        break;
      }
    }
  }
} catch (e) { 
  console.log('FRED Treasury error: ' + e.message); 
}

// 8. FETCH MARKETWATCH RSS HEADLINES
try {
  const rssResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.marketwatch.com/rss/topstories',
    timeout: 30000,
    json: false
  });

  if (rssResponse && typeof rssResponse === 'string') {
    const titleMatches = rssResponse.match(/<title>([^<]+)<\/title>/g);

    if (titleMatches && titleMatches.length > 1) {
      const titles = [];
      for (let i = 1; i < Math.min(titleMatches.length, 9); i++) {
        let title = titleMatches[i].replace(/<\/?title>/g, '');
        title = title.trim();
        title = title.replace(/&#x201c;/g, '"');
        title = title.replace(/&#x201d;/g, '"');
        title = title.replace(/&#x2019;/g, "'");
        title = title.replace(/&#x2018;/g, "'");
        title = title.replace(/&#x2014;/g, ' - ');
        title = title.replace(/&#x2013;/g, '-');
        title = title.replace(/&amp;/g, '&');
        title = title.replace(/&quot;/g, '"');
        title = title.replace(/&#xa0;/g, ' ');

        if (title.length > 10) {
          titles.push(i + '. ' + title);
        }
      }

      if (titles.length > 0) {
        results.headlines = titles.join('\n');
      }
    }
  }
} catch (e) { 
  console.log('RSS error: ' + e.message); 
}

return [{ json: results }];

// ============================================
// SPLIT WATCHLIST & FETCH STOCK PRICES v6.0
// IPv4 Fix + Rate Limiting + Retry Logic
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const watchlistStr = $input.first().json.watchlist || '';
const symbols = watchlistStr.split(',').map(s => s.trim()).filter(s => s.length > 0);

const stocks = [];

for (const symbol of symbols) {
  let retries = 3;
  let success = false;

  while (retries > 0 && !success) {
    try {
      const data = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(symbol) + '?interval=1d&range=1d',
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
        timeout: 10000
      });

      if (data && data.chart && data.chart.result && data.chart.result[0]) {
        const meta = data.chart.result[0].meta;
        const price = meta.regularMarketPrice;
        const prevClose = meta.chartPreviousClose || meta.previousClose;

        let priceStr = 'N/A';
        let changeStr = 'N/A';

        if (price) {
          priceStr = '$' + price.toFixed(2);

          if (prevClose && prevClose > 0) {
            const changeAmt = price - prevClose;
            const changePct = (changeAmt / prevClose) * 100;
            const sign = changePct >= 0 ? '+' : '';
            changeStr = sign + changePct.toFixed(2) + '%';
          }
        }

        stocks.push({ symbol, price: priceStr, change: changeStr });
        success = true;
      }
    } catch (e) {
      retries--;
      if (retries > 0) {
        await new Promise(r => setTimeout(r, 1500));
      } else {
        stocks.push({ symbol, price: 'N/A', change: 'N/A' });
      }
    }
  }

  // Rate limit delay between stocks
  await new Promise(r => setTimeout(r, 500));
}

let summary = 'Stock data unavailable';
if (stocks.length > 0) {
  summary = stocks.map(s => '  ' + s.symbol + ': ' + s.price + ' (' + s.change + ')').join('\n');
}

return [{ json: { watchlistSummary: summary, stockCount: stocks.length } }];

// ============================================
// COMBINE ALL DATA - MarketPulse v6.0
// Merges market data + stock prices into one
// ============================================

const items = $input.all();
const combined = {};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(j)) {
    if (j[key] !== undefined && j[key] !== null) {
      combined[key] = j[key];
    }
  }
}

return [{ json: combined }];

// ============================================
// COMPOSE TELEGRAM MESSAGE - MarketPulse v6.0
// New: Market Screener section with indices
// ============================================

const items = $input.all();
const now = new Date();

let d = {
  fearGreedValue: 'N/A',
  fearGreedClassification: 'Unknown',
  fearGreedChange1d: 'N/A',
  fearGreedChange1w: 'N/A',
  gdpValue: 'N/A',
  gdpYear: 'N/A',
  cpiValue: 'N/A',
  cpiYear: 'N/A',
  unemploymentValue: 'N/A',
  unemploymentYear: 'N/A',
  fedRateValue: 'N/A',
  treasury10Y: 'N/A',
  sp500: 'N/A',
  sp500Change: 'N/A',
  dowJones: 'N/A',
  dowJonesChange: 'N/A',
  vix: 'N/A',
  vixChange: 'N/A',
  gold: 'N/A',
  goldChange: 'N/A',
  watchlistSummary: 'N/A',
  llmAnalysis: 'Analysis unavailable'
};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(d)) {
    if (j[key] && j[key] !== 'N/A' && j[key] !== 'Unknown' && j[key] !== 'Analysis unavailable') {
      d[key] = j[key];
    }
  }
  if (j.text && j.text.length > 30) d.llmAnalysis = j.text;
  if (j.response && j.response.length > 30) d.llmAnalysis = j.response;
}

const dateStr = now.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// Fear & Greed emoji indicator
const fgScore = parseInt(d.fearGreedValue) || 0;
let fgEmoji = '⚪';
if (fgScore >= 75) fgEmoji = '🟢🟢';
else if (fgScore >= 55) fgEmoji = '🟢';
else if (fgScore >= 45) fgEmoji = '🟡';
else if (fgScore >= 25) fgEmoji = '🟠';
else if (fgScore > 0) fgEmoji = '🔴';

// VIX emoji indicator
const vixVal = parseFloat(d.vix) || 0;
let vixEmoji = '⚪';
if (vixVal >= 30) vixEmoji = '🔴 HIGH';
else if (vixVal >= 20) vixEmoji = '🟠 ELEVATED';
else if (vixVal >= 12) vixEmoji = '🟢 NORMAL';
else if (vixVal > 0) vixEmoji = '🟢🟢 LOW';

// Market direction arrows
function arrow(changeStr) {
  if (!changeStr || changeStr === 'N/A') return '';
  return changeStr.startsWith('+') ? '▲' : '▼';
}

const message = `📊 MarketPulse Daily Digest
━━━━━━━━━━━━━━━━━━━━
📅 ${dateStr}

🎯 FEAR & GREED INDEX ${fgEmoji}
Score: ${d.fearGreedValue}/100 | ${d.fearGreedClassification}
Change: ${d.fearGreedChange1d} (1d) | ${d.fearGreedChange1w} (1w)

📈 MARKET SCREENER
${arrow(d.sp500Change)} S&P 500: ${d.sp500} (${d.sp500Change})
${arrow(d.dowJonesChange)} Dow Jones: ${d.dowJones} (${d.dowJonesChange})
${arrow(d.vixChange)} VIX: ${d.vix} (${d.vixChange}) ${vixEmoji}
${arrow(d.goldChange)} Gold: ${d.gold} (${d.goldChange})

📊 ECONOMIC INDICATORS (USA)
• GDP Growth (${d.gdpYear}): ${d.gdpValue}
• Inflation/CPI (${d.cpiYear}): ${d.cpiValue}
• Unemployment (${d.unemploymentYear}): ${d.unemploymentValue}
• Fed Funds Rate: ${d.fedRateValue}
• 10Y Treasury: ${d.treasury10Y}

📋 WATCHLIST
${d.watchlistSummary}

💡 AI ANALYSIS
${d.llmAnalysis}

━━━━━━━━━━━━━━━━━━━━
⚠️ Disclaimer: AI-generated analysis for informational purposes only. Not financial advice.

📎 Sources: CNN Fear & Greed, FRED, MarketWatch, Yahoo Finance

MarketPulse v6.0 | Manus AI & Claude Code`;

return [{ json: { message: message, timestamp: now.toISOString() } }];

const alertMessage = `⚠️ MarketPulse Error

Time: ${new Date().toISOString()}

Check n8n dashboard for details.`;
return [{ json: { alertMessage } }];
